import {STORY_PRESETS,generateCampaign,createWeekPlan,srt,packFiles,zipFiles,validatePlatformCopies} from './core.mjs';
import {drawStory,recordStory,supportsRecording} from './renderer.mjs';
import {createVideoCache} from './video-cache.mjs';
const $=id=>document.getElementById(id),KEY='purrflow.creator-kit.v1',platforms=['facebook','instagram','youtube','x','tiktok'];
let campaign,plan=[],activePlatform='facebook',activePreset=STORY_PRESETS[0].id,rendered=null,videoURL=null,videoCache,playing=false,recording=false,dirty=false,lastTick=0,playTime=0,toastTimer;
const canvas=$('story-canvas');
function notify(message,error=false){const t=$('toast');t.textContent=message;t.style.background=error?'#934832':'#153f34';t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,6000);}
function readForm(){return Object.fromEntries(['title','hook','setup','payoff','tone','language'].map(k=>[k,$(k).value]));}
function inputStory(value){for(const k of ['title','hook','setup','payoff','tone','language'])if(value[k]!==undefined)$(k).value=value[k];}
function showCopy(){const index=platforms.indexOf(activePlatform);$('copy-label').textContent=['Facebook','Instagram','YouTube','X','TikTok'][index]+' caption';$('platform-copy').value=campaign.platforms[activePlatform];countCopy();}
function countCopy(){const value=$('platform-copy').value;const n=Array.from(value).length;$('copy-count').textContent=`${n} characters${activePlatform==='x'?' · keep under your platform limit':''}`;}
function invalidateVideo(){videoCache?.invalidate();clearVideo();}
function clearVideo(){rendered=null;if(videoURL)URL.revokeObjectURL(videoURL);videoURL=null;$('video-download').hidden=true;$('export').textContent='Export creator kit ↓';const s=supportsRecording();$('render-state').textContent=s.supported?`Exports ${s.extension.toUpperCase()} · silent · 720 × 1280 · takes 15 seconds`:'Video rendering is unavailable here. Caption and ZIP exports still work.';}
function showVideo(result,{restored=false}={}){clearVideo();rendered=result;videoURL=URL.createObjectURL(result.blob);$('video-download').href=videoURL;$('video-download').download=slug()+'.'+result.extension;$('video-download').hidden=false;$('render-state').textContent=`${restored?'Restored from this browser':'Ready'} · ${result.extension.toUpperCase()} · ${(result.blob.size/1048576).toFixed(1)} MB · 720 × 1280 · silent`;$('export').textContent='Export kit + video ↓';}
function setDirty(){dirty=true;invalidateVideo();$('save-state').textContent='Story edited · rebuild kit';for(const k of ['export','render','srt'])$(k).disabled=true;}
function renderFrame(t=playTime){drawStory(canvas,t,campaign,activePreset);$('scrub').value=t;$('time').textContent=`0:${String(Math.floor(t)).padStart(2,'0')} / 0:15`;}
function pause(){playing=false;$('play').textContent='▶ Play';$('play').setAttribute('aria-label','Play animation');}
function build({announce=true}={}){pause();campaign=generateCampaign(readForm());dirty=false;invalidateVideo();showCopy();playTime=0;renderFrame();for(const k of ['export','srt'])$(k).disabled=false;$('render').disabled=!supportsRecording().supported;$('save-state').textContent='Kit updated · save to keep';if(announce)notify('Your story, five captions and timed subtitles are ready.');}
function loadPreset(id){const p=STORY_PRESETS.find(s=>s.id===id);if(!p)throw new Error('Choose an available story.');activePreset=p.id;$('preset').value=p.id;inputStory({...p,tone:$('tone').value,language:$('language').value});build({announce:false});}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function slug(){return campaign.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'mochi-story';}
function state(){const startDate=$('start-date').value,videosPerDay=Number($('daily').value),nextPlan=createWeekPlan({startDate,videosPerDay});validatePlatformCopies(campaign.platforms);return {version:1,presetId:activePreset,input:{...readForm(),source:'animation'},platforms:campaign.platforms,startDate,videosPerDay,plan:nextPlan};}
function validateRestore(value){if(!value||value.version!==1||!STORY_PRESETS.some(p=>p.id===value.presetId)||!value.input||value.input.source&&value.input.source!=='animation')throw new Error('This is not a supported animation workspace.');const next=generateCampaign({...value.input,source:'animation'}),nextPlan=createWeekPlan({startDate:value.startDate,videosPerDay:value.videosPerDay});if(value.platforms)next.platforms=validatePlatformCopies(value.platforms);return {value,next,nextPlan};}
function restore(value){const validated=validateRestore(value);activePreset=value.presetId;$('preset').value=activePreset;inputStory(value.input);campaign=validated.next;plan=validated.nextPlan;$('start-date').value=value.startDate;$('daily').value=value.videosPerDay;dirty=false;invalidateVideo();pause();playTime=0;showCopy();renderFrame();showPlan();for(const k of ['export','srt'])$(k).disabled=false;$('render').disabled=!supportsRecording().supported;$('save-state').textContent='Workspace restored';}
function save(){if(dirty)throw new Error('Build your updated story before saving.');try{localStorage.setItem(KEY,JSON.stringify(videoCache.withReference(state())));}catch{throw new Error('This browser could not save the workspace. Storage may be full or blocked. Download a workspace backup to keep your draft.');}$('save-state').textContent='Saved in this browser';notify('Workspace saved. Download a backup to use it elsewhere.');}
function showPlan(){const grid=$('week-grid');grid.replaceChildren();$('week-summary').textContent=`${plan.length} story briefs · 7 days · ${$('daily').value} per day · Asia/Manila`;for(const date of [...new Set(plan.map(p=>p.date))]){const card=document.createElement('article');card.className='day-card';const heading=document.createElement('h3');heading.textContent=new Date(date+'T12:00:00+08:00').toLocaleDateString('en-PH',{weekday:'long',month:'short',day:'numeric',timeZone:'Asia/Manila'});card.append(heading);for(const item of plan.filter(p=>p.date===date)){const row=document.createElement('div');row.className='plan-item';const time=document.createElement('span');time.textContent=item.time+' · PLANNED';const title=document.createElement('strong');title.textContent=item.title;const use=document.createElement('button');use.textContent='Use this brief ↗';use.onclick=()=>{if(recording)return;activePreset=item.presetId;$('preset').value=activePreset;inputStory(item);build({announce:false});setView('studio');notify('Calendar brief loaded. You can edit its story before exporting.');};row.append(time,title,use);card.append(row);}grid.append(card);}}
function setView(name){if(recording){notify('Keep this studio open while the video renders.');return;}for(const view of ['studio','calendar','guide'])$(view+'-view').hidden=view!==name;document.querySelectorAll('[data-view]').forEach(b=>{const on=b.dataset.view===name;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});pause();window.scrollTo({top:0,behavior:'smooth'});}
function safe(fn){return async(...args)=>{try{await fn(...args);}catch(error){notify(error.message||'Something went wrong. Please try again.',true);}};}
for(const preset of STORY_PRESETS){const option=document.createElement('option');option.value=preset.id;option.textContent=preset.title;$('preset').append(option);}
for(const k of ['title','hook','setup','payoff','tone','language'])$(k).addEventListener('input',setDirty);
$('preset').addEventListener('change',safe(()=>loadPreset($('preset').value)));
$('build').onclick=safe(()=>build());$('save').onclick=safe(save);
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
document.querySelectorAll('[data-platform]').forEach(b=>{b.onclick=()=>{activePlatform=b.dataset.platform;document.querySelectorAll('[data-platform]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));showCopy();};b.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const current=platforms.indexOf(activePlatform),next=e.key==='Home'?0:e.key==='End'?4:(current+(e.key==='ArrowRight'?1:4))%5;document.querySelector(`[data-platform="${platforms[next]}"]`).click();document.querySelector(`[data-platform="${platforms[next]}"]`).focus();};});
$('platform-copy').addEventListener('input',()=>{campaign.platforms[activePlatform]=$('platform-copy').value;countCopy();$('save-state').textContent='Caption edited · save to keep';});
$('copy-caption').onclick=safe(async()=>{validatePlatformCopies(campaign.platforms);await navigator.clipboard.writeText($('platform-copy').value);notify('Caption copied.');});
$('play').onclick=()=>{if(recording)return;if(playing)pause();else{if(playTime>=14.95)playTime=0;playing=true;lastTick=performance.now();$('play').textContent='Ⅱ Pause';$('play').setAttribute('aria-label','Pause animation');}};
function animate(now){if(playing&&!recording){playTime=Math.min(15,playTime+(now-lastTick)/1000);renderFrame();if(playTime>=15)pause();}lastTick=now;requestAnimationFrame(animate);}requestAnimationFrame(animate);
$('scrub').oninput=()=>{pause();playTime=Number($('scrub').value);renderFrame();};
function previewMode(sample){if(recording)return;pause();canvas.hidden=sample;$('sample').hidden=!sample;$('playback-controls').hidden=sample;$('sample-note').hidden=!sample;$('sample-mode').classList.toggle('selected',sample);$('sample-mode').setAttribute('aria-pressed',String(sample));$('animation-mode').classList.toggle('selected',!sample);$('animation-mode').setAttribute('aria-pressed',String(!sample));if(!sample)$('sample').pause();}
$('sample-mode').onclick=()=>previewMode(true);$('animation-mode').onclick=()=>previewMode(false);
const support=supportsRecording();$('render').disabled=!support.supported;$('render-state').textContent=support.supported?`Exports ${support.extension.toUpperCase()} · silent · 720 × 1280 · takes 15 seconds`:'Video rendering is unavailable here. Use current Chrome or Edge; caption and ZIP exports still work.';
$('render').onclick=safe(async()=>{if(dirty)throw new Error('Build your edited story first.');const snapshot=state();invalidateVideo();const ticket=videoCache.begin();pause();previewMode(false);recording=true;const controls=[...document.querySelectorAll('input,textarea,select,button')],prior=controls.map(el=>el.disabled);controls.forEach(el=>el.disabled=true);try{const result=await recordStory(canvas,campaign,activePreset,{onProgress:p=>{$('render-state').textContent=`Rendering ${Math.round(p*100)}% · keep this tab open`;}});if(ticket!==videoCache.begin())return;showVideo(result);$('render-state').textContent+=' · saving in this browser…';const saved=await videoCache.persist(snapshot,result,ticket);if(saved.status==='stale')return;showVideo(result);$('save-state').textContent=saved.status==='saved'?'Workspace + video saved':saved.status==='workspace-only'?'Workspace saved · download video':'Download a backup';notify(saved.message,saved.status!=='saved');}finally{recording=false;controls.forEach((el,i)=>el.disabled=prior[i]);playTime=0;renderFrame();}});
$('srt').onclick=safe(()=>download(new Blob([srt(campaign.cues)],{type:'application/x-subrip'}),slug()+'.srt'));
$('export').onclick=safe(async()=>{if(dirty)throw new Error('Build your edited story first.');const snapshot=state(),files=packFiles(campaign,snapshot.plan);files['workspace.json']=JSON.stringify(snapshot,null,2);files['README.txt']+='\nVIDEO: This kit uses a silent procedural illustration, not a new Google Flow generation. AI sample preview is separate.\n';if(rendered)files['video/'+slug()+'.'+rendered.extension]=new Uint8Array(await rendered.blob.arrayBuffer());download(new Blob([zipFiles(files)],{type:'application/zip'}),slug()+'-creator-kit.zip');notify(rendered?'Creator kit exported with your rendered video.':'Creator kit exported. Render a video first to include it.');});
$('plan').onclick=safe(()=>{plan=createWeekPlan({startDate:$('start-date').value,videosPerDay:Number($('daily').value)});showPlan();notify('Seven-day editorial plan created. No posts have been scheduled.');});
for(const id of ['start-date','daily'])$(id).onchange=safe(()=>{plan=createWeekPlan({startDate:$('start-date').value,videosPerDay:Number($('daily').value)});showPlan();$('save-state').textContent='Calendar edited · save to keep';});
$('csv').onclick=safe(()=>{const snapshot=state();download(new Blob([packFiles(campaign,snapshot.plan)['week-plan.csv']],{type:'text/csv;charset=utf-8'}),'mochi-week-plan.csv');});
$('backup').onclick=safe(()=>{if(dirty)throw new Error('Build your edited story first.');download(new Blob([JSON.stringify(state(),null,2)],{type:'application/json'}),'purrflow-workspace.json');});
$('import-workspace').onchange=safe(async()=>{const file=$('import-workspace').files[0];if(!file)return;if(file.size>150000)throw new Error('Workspace file is too large. Maximum 150 KB.');const ticket=videoCache.begin(),value=JSON.parse(await file.text());if(ticket!==videoCache.begin()){notify('The workspace changed while the backup was opening. Choose the backup again to restore it.');return;}restore(value);try{localStorage.setItem(KEY,JSON.stringify(state()));}catch{throw new Error('Backup restored, but this browser could not save it. Keep your downloaded backup; storage may be full or blocked.');}notify('Workspace restored and saved. Render this story to create its video; JSON backups contain no video.');$('import-workspace').value='';});
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('start-date').value=today;
loadPreset(activePreset);plan=createWeekPlan({startDate:today,videosPerDay:3});showPlan();
let savedWorkspace;
try{const stored=localStorage.getItem(KEY);if(stored){savedWorkspace=JSON.parse(stored);restore(savedWorkspace);}}catch{savedWorkspace=null;notify('The saved draft could not be restored. A fresh draft is ready; your old browser data was not overwritten.',true);}
videoCache=createVideoCache({saveWorkspace:value=>localStorage.setItem(KEY,JSON.stringify(value)),retireReference:()=>{const stored=localStorage.getItem(KEY);if(!stored)return;let value;try{value=JSON.parse(stored);}catch{return;}if(value?.videoCache){delete value.videoCache;localStorage.setItem(KEY,JSON.stringify(value));}},reportFailure:message=>notify(message,true)});
if(savedWorkspace){const ticket=videoCache.begin();videoCache.restore(savedWorkspace).then(result=>{if(ticket!==videoCache.begin())return;if(result.status==='restored'){showVideo(result.video,{restored:true});$('save-state').textContent='Workspace + video restored';notify('Your saved workspace and matching video are ready.');}else if(result.message)notify(result.message,result.status==='unavailable');});}
